function shuffle(array) {
  const copy = [...array];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

function validateDataset(gameId, dataset) {
  if (!Array.isArray(dataset)) {
    throw new HttpsError(
      "internal",
      `El dataset de ${gameId} no es un array`
    );
  }

  if (dataset.length === 0) {
    throw new HttpsError(
      "internal",
      `El dataset de ${gameId} está vacío`
    );
  }

  const invalidItem = dataset.find((item) => !item || !item.id);
  if (invalidItem) {
    throw new HttpsError(
      "internal",
      `Hay elementos sin id en el dataset de ${gameId}`
    );
  }
}

async function ensureGameChallenge(gameId, dataset, buildPayload) {
  validateDataset(gameId, dataset);

  const dateKey = madridTodayKey();

  const challengeRef = db
    .collection("groups")
    .doc(GROUP_ID)
    .collection("daily_game_challenges")
    .doc(`${gameId}_${dateKey}`);

  const rotationRef = db
    .collection("groups")
    .doc(GROUP_ID)
    .collection("daily_game_rotations")
    .doc(gameId);

  await db.runTransaction(async (tx) => {
    const existingChallenge = await tx.get(challengeRef);
    if (existingChallenge.exists) {
      console.log(`[${gameId}] challenge ya existe para ${dateKey}`);
      return;
    }

    const rotationSnap = await tx.get(rotationRef);

    let remainingIds = [];
    if (rotationSnap.exists) {
      remainingIds = Array.isArray(rotationSnap.data().remainingIds)
        ? rotationSnap.data().remainingIds
        : [];
    }

    const allIds = dataset.map((item) => item.id);

    if (!remainingIds.length) {
      remainingIds = shuffle(allIds);
    }

    const selectedId = remainingIds.shift();

    if (!selectedId) {
      throw new HttpsError(
        "internal",
        `No se pudo seleccionar id para el juego ${gameId}`
      );
    }

    const selectedItem = dataset.find((item) => item.id === selectedId);

    if (!selectedItem) {
      throw new HttpsError(
        "internal",
        `No se encontró elemento para el juego ${gameId} con id ${selectedId}`
      );
    }

    const payload = buildPayload(selectedItem);

    if (!payload || typeof payload !== "object") {
      throw new HttpsError(
        "internal",
        `Payload inválido para el juego ${gameId}`
      );
    }

    tx.set(challengeRef, {
      gameId,
      dateKey,
      payload,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    tx.set(
      rotationRef,
      {
        remainingIds,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      },
      { merge: true }
    );

    console.log(`[${gameId}] challenge creado para ${dateKey} con id ${selectedId}`);
  });
}

exports.ensureTodayDailyGames = onCall(
  {
    region: "europe-west1",
    timeoutSeconds: 120,
    memory: "256MiB",
  },
  async (request) => {
    if (!request.auth) {
      throw new HttpsError("unauthenticated", "Debes estar autenticado.");
    }

    const result = {
      ok: true,
      dateKey: madridTodayKey(),
      created: [],
      failed: [],
    };

    const safeEnsure = async (gameId, dataset, buildPayload) => {
      try {
        await ensureGameChallenge(gameId, dataset, buildPayload);
        result.created.push(gameId);
      } catch (error) {
        console.error(`Error creando challenge de ${gameId}:`, error);
        result.failed.push({
          gameId,
          message: error?.message || String(error),
        });
      }
    };

    await safeEnsure(
      "loldle",
      LOL_CHAMPIONS,
      (item) => ({
        targetId: item.id,
      })
    );

    await safeEnsure(
      "pokedle",
      POKEMON_GEN123,
      (item) => ({
        targetId: item.id,
      })
    );

    await safeEnsure(
      "wordle",
      WORDLE_WORDS.map((word) => ({
        id: word,
        word,
      })),
      (item) => ({
        solution: item.word,
        wordLength: item.word.length,
      })
    );

    await safeEnsure(
      "sudoku",
      SUDOKU_PUZZLES,
      (item) => ({
        puzzle: item.puzzle,
        solution: item.solution,
        difficulty: item.difficulty,
      })
    );

    await safeEnsure(
      "queens",
      QUEENS_PUZZLES,
      (item) => ({
        size: item.size,
        regionsRows: item.regions.map((row) => row.join(",")),
        solution: item.solution,
        difficulty: item.difficulty,
      })
    );
    await safeEnsure(
      "zip",
      ZIP_PUZZLES,
      (item) => ({
        size: item.size,
        points: item.points,
        solutionPath: item.solutionPath,
      })
    );

    await safeEnsure(
      "patches",
      PATCHES_PUZZLES,
      (item) => ({
        size: item.size,
        pieces: item.pieces,
        solutionRects: item.solutionRects,
      })
    );

    await safeEnsure(
      "tango",
      TANGO_PUZZLES,
      (item) => ({
        size: item.size,
        initialBoardRows: item.initialBoard.map((row) =>
          row.map((cell) => (cell === null ? "_" : String(cell))).join(",")
        ),
        solutionRows: item.solution.map((row) => row.join(",")),
        constraints: item.constraints,
        difficulty: item.difficulty,
      })
    );
    result.ok = result.failed.length === 0;
    return result;
  }
);